const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/client\"\n}\n\n// ----------------------------------------------------\n// 1. MULTI-BRANCH SYSTEM (منظومة الفروع المتعددة)\n// ----------------------------------------------------\nmodel Branch {\n  id            String             @id @default(cuid())\n  name          String // e.g. \"فرع حدائق القبة\", \"فرع مدينة نصر\"\n  code          String             @unique // \"BR-KOBBA\", \"BR-NASR-CITY\"\n  address       String\n  phone         String\n  whatsapp      String?\n  googleMapsUrl String?\n  isActive      Boolean            @default(true)\n  createdAt     DateTime           @default(now())\n  users         User[]\n  specialists   Specialist[]\n  bookings      Booking[]\n  tickets       Ticket[]\n  products      Product[]\n  ledgers       SpecialistLedger[]\n  offers        Offer[]\n  chatMessages  ChatMessage[]\n  shifts        CashShift[]\n  expenses      TreasuryExpense[]\n}\n\n// ----------------------------------------------------\n// 2. STAFF & USERS RBAC (المستخدمين والصلاحيات)\n// ----------------------------------------------------\nmodel User {\n  id                String      @id @default(cuid())\n  name              String\n  username          String      @unique // maestro, hadayek-mgr, nasr-mgr, cashier1, etc.\n  passwordHash      String // 123456789\n  pin               String      @default(\"157230\") // PIN Code\n  phone             String?\n  role              String      @default(\"owner\") // owner, general_manager, manager, cashier, specialist, worker\n  branchId          String?\n  branch            Branch?     @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  permissions       String? // JSON array\n  isActive          Boolean     @default(true)\n  createdAt         DateTime    @default(now())\n  specialistProfile Specialist?\n}\n\n// ----------------------------------------------------\n// 3. SPECIALISTS / BARBERS (المتخصصين وكراسي الحلاقة)\n// ----------------------------------------------------\nmodel Specialist {\n  id           String  @id @default(cuid())\n  userId       String? @unique\n  user         User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n  branchId     String\n  branch       Branch  @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  name         String\n  phone        String?\n  photo        String? // ImgBB URL\n  title        String  @default(\"خبير حلاقة وتصفيف\")\n  chairNumber  Int     @default(1)\n  status       String  @default(\"AVAILABLE\") // AVAILABLE, WITH_CLIENT, BREAK, OFF_DUTY, DAY_OFF, ABSENT\n  statusReason String? // سبب التعطيل أو الملاحظة (مثلاً: إجازة أسبوعية، استراحة غداء، انتهى اليوم ومشي)\n  rating       Float   @default(4.9)\n\n  // Compensation & Payroll scheme\n  payType        String @default(\"SALARY_PLUS_COMMISSION\") // DAILY, WEEKLY, MONTHLY, COMMISSION_ONLY, SALARY_PLUS_COMMISSION\n  baseSalary     Float  @default(0)\n  commissionRate Float  @default(20) // %\n\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  bookings Booking[]\n  tickets  Ticket[]\n  ledgers  SpecialistLedger[]\n}\n\n// ----------------------------------------------------\n// 4. DYNAMIC SERVICES CATALOG (الخدمات التجميلية والحلاقة)\n// ----------------------------------------------------\nmodel Service {\n  id              String   @id @default(cuid())\n  nameAr          String\n  nameEn          String?\n  category        String   @default(\"HAIR\") // HAIR, BEARD, SKIN_CARE, VIP_PACKAGES, KIDS, COLOR_KERATIN\n  price           Float\n  durationMinutes Int      @default(30)\n  description     String?\n  image           String? // ImgBB URL\n  sortOrder       Int      @default(0)\n  isActive        Boolean  @default(true)\n  createdAt       DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 5. CUSTOMER DATABASE & CRM (قاعدة بيانات العملاء والتسويق)\n// ----------------------------------------------------\nmodel Customer {\n  id               String    @id @default(cuid())\n  name             String\n  phone            String    @unique\n  email            String?\n  passwordHash     String?\n  isVerified       Boolean   @default(false)\n  verificationCode String?\n  avatar           String?\n  notes            String?\n  vipLevel         String    @default(\"REGULAR\") // REGULAR, VIP, GOLD_MEMBER\n  totalVisits      Int       @default(0)\n  totalSpent       Float     @default(0)\n  createdAt        DateTime  @default(now())\n  lastVisitAt      DateTime?\n\n  bookings Booking[]\n  tickets  Ticket[]\n}\n\n// ----------------------------------------------------\n// 6. APPOINTMENTS & BOOKINGS (الحجوزات المسبقة)\n// ----------------------------------------------------\nmodel Booking {\n  id                 String      @id @default(cuid())\n  bookingNumber      String      @unique // SAD-XXXX\n  customerId         String\n  customer           Customer    @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  branchId           String\n  branch             Branch      @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  specialistId       String?\n  specialist         Specialist? @relation(fields: [specialistId], references: [id], onDelete: SetNull)\n  serviceIds         String // JSON array: [{ id, nameAr, price, durationMinutes }]\n  bookingDate        String // YYYY-MM-DD\n  timeSlot           String // e.g. \"05:00 PM\"\n  status             String      @default(\"CONFIRMED\") // PENDING, CONFIRMED, IN_CHAIR, COMPLETED, CANCELLED, NO_SHOW\n  notes              String?\n  totalAmount        Float       @default(0)\n  reminderSentAt     DateTime?\n  overdueAlertSentAt DateTime?\n  createdAt          DateTime    @default(now())\n  updatedAt          DateTime    @updatedAt\n}\n\n// ----------------------------------------------------\n// 7. IN-CHAIR LIVE TICKETS (شاشة المتخصص والكرسي اللحظية)\n// ----------------------------------------------------\nmodel Ticket {\n  id            String     @id @default(cuid())\n  ticketNumber  String     @unique // CHAIR-XXXX\n  branchId      String\n  branch        Branch     @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  specialistId  String\n  specialist    Specialist @relation(fields: [specialistId], references: [id], onDelete: Cascade)\n  customerId    String?\n  customer      Customer?  @relation(fields: [customerId], references: [id], onDelete: SetNull)\n  customerName  String\n  customerPhone String?\n  chairNumber   Int        @default(1)\n  status        String     @default(\"IN_CHAIR\") // IN_CHAIR, READY_FOR_CASHIER, COMPLETED, CANCELLED\n\n  services    String @default(\"[]\") // JSON: [{ id, nameAr, price, addedAt }]\n  retailItems String @default(\"[]\") // JSON: [{ id, nameAr, price, qty, total }]\n\n  servicesTotal Float  @default(0)\n  retailTotal   Float  @default(0)\n  discount      Float  @default(0)\n  tipAmount     Float  @default(0)\n  finalAmount   Float  @default(0)\n  paymentMethod String @default(\"CASH\") // CASH, CARD, INSTAPAY, VODAFONE_CASH\n\n  startTime       DateTime  @default(now())\n  endTime         DateTime?\n  durationMinutes Int?\n\n  cashierName String?\n  notes       String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 8. RETAIL BEAUTY PRODUCTS (بضاعة التجميل ومستحضرات العناية)\n// ----------------------------------------------------\nmodel Product {\n  id            String   @id @default(cuid())\n  branchId      String?\n  branch        Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  nameAr        String\n  category      String   @default(\"STYLING\") // STYLING, BEARD_CARE, SKIN_CARE, PERFUMES, ACCESSORIES\n  price         Float\n  costPrice     Float    @default(0)\n  stockQty      Int      @default(50)\n  minStockAlert Int      @default(10)\n  image         String? // ImgBB URL\n  barcode       String?\n  isActive      Boolean  @default(true)\n  createdAt     DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 9. SPECIALIST LEDGER & PAYROLL (سجل حسابات وسلف وأجور المتخصصين)\n// ----------------------------------------------------\nmodel SpecialistLedger {\n  id           String     @id @default(cuid())\n  specialistId String\n  specialist   Specialist @relation(fields: [specialistId], references: [id], onDelete: Cascade)\n  branchId     String\n  branch       Branch     @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  type         String // SALARY_PAYOUT, COMMISSION_EARNED, ADVANCE_WITHDRAWAL, BONUS, DEDUCTION\n  amount       Float\n  notes        String?\n  date         DateTime   @default(now())\n  recordedBy   String     @default(\"المالك (Maestro)\")\n  createdAt    DateTime   @default(now())\n}\n\n// ----------------------------------------------------\n// 10. SYSTEM GLOBAL SETTINGS & KILL SWITCH (إعدادات النظام والتحكم)\n// ----------------------------------------------------\nmodel SystemSettings {\n  id               String  @id @default(\"default-settings\")\n  salonNameAr      String  @default(\"مجموعة صالونات وسبا الباشا VIP\")\n  salonNameEn      String  @default(\"EL BASHA LUXURY SALON & SPA\")\n  logoUrl          String  @default(\"/dakn-logo.jpg\")\n  systemLocked     Boolean @default(false)\n  lockMessage      String  @default(\"النظام مغلق مؤقتاً لأعمال الصيانة والتحديث.\")\n  hadayekPhone     String  @default(\"01210103025\")\n  nasrCityPhone    String  @default(\"01556782015\")\n  hotline          String  @default(\"01210103025\")\n  whatsappNumber   String  @default(\"01210103025\")\n  facebookUrl      String  @default(\"https://www.facebook.com/DaknElbashaSalon\")\n  instagramUrl     String?\n  defaultOpenHour  String  @default(\"11:00 AM\")\n  defaultCloseHour String  @default(\"01:00 AM\")\n\n  // Weekly Day Off & Booking Policies\n  weeklyDayOff          String  @default(\"MONDAY\") // MONDAY, TUESDAY, WEDNESDAY, THURSDAY, FRIDAY, SATURDAY, SUNDAY, NONE\n  isDayOffEnabled       Boolean @default(true)\n  dayOffMessage         String  @default(\"عفواً، صالونات وسبا الباشا في عطلة أسبوعية يوم الإثنين - نتشرف بحجز موعدكم طوال باقي أيام الأسبوع ✂️\")\n  bookingSlotInterval   Int     @default(30) // in minutes\n  reminderMinutesBefore Int     @default(15) // reminder 15 min before\n  receiptFooterNotes    String  @default(\"شكراً لزيارتكم مجموعة صالونات وسبا الباشا VIP 👑 تجربة ملوكية استثنائية\")\n\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 11. DYNAMIC ROYAL OFFERS & PACKAGES (العروض الملكية والباكدجات)\n// ----------------------------------------------------\nmodel Offer {\n  id              String   @id @default(cuid())\n  titleAr         String // e.g. \"عرض العريس الملكي\"\n  badge           String? // \"خصم 46%\", \"VIP\", \"لفترة محدودة\"\n  price           Float // 3500\n  oldPrice        Float? // 4000\n  discountPercent Int? // 15\n  image           String // \"/offers/offer-groom-3500.jpg\"\n  description     String?\n  features        String   @default(\"[]\") // JSON array of bullet points\n  branchId        String? // null = متاح في كل الفروع\n  branch          Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  isActive        Boolean  @default(true)\n  sortOrder       Int      @default(0)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 12. IN-APP LIVE CHAT (شات مباشر وتواصل فوري بين الصالون والعملاء)\n// ----------------------------------------------------\nmodel ChatMessage {\n  id            String   @id @default(cuid())\n  branchId      String?\n  branch        Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  customerId    String?\n  customerName  String   @default(\"عميل VIP\")\n  customerPhone String?\n  bookingId     String?\n  sender        String // \"CUSTOMER\" or \"SALON\"\n  senderName    String   @default(\"خدمة عملاء مجموعة الباشا VIP\")\n  message       String\n  isRead        Boolean  @default(false)\n  createdAt     DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 13. CASH SHIFTS & DRAWER CLOSING (إقفال الورديات وتسليم النقدية)\n// ----------------------------------------------------\nmodel CashShift {\n  id          String    @id @default(cuid())\n  shiftNumber String    @unique // SHIFT-XXXX\n  branchId    String\n  branch      Branch    @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  cashierName String\n  openedAt    DateTime  @default(now())\n  closedAt    DateTime?\n  status      String    @default(\"OPEN\") // OPEN, CLOSED\n\n  // Financial breakdown\n  ticketsCount      Int   @default(0)\n  servicesTotal     Float @default(0) // إجمالي الحلاقة\n  retailTotal       Float @default(0) // إجمالي مبيعات المنتجات\n  cashCollected     Float @default(0) // نقدية كاش مقبوضة\n  visaCollected     Float @default(0) // فيزا وماستر\n  instapayCollected Float @default(0) // انستاباي\n  vodafoneCollected Float @default(0) // فودافون كاش\n\n  advancesPayouts Float @default(0) // سلف ومستحقات خرجت نقداً\n  expensesTotal   Float @default(0) // مصروفات ونثريات خرجت نقداً\n\n  expectedCash Float @default(0) // النقدية الصافية المطلوبة بالدرج\n  actualCash   Float @default(0) // النقدية الفعلية المسلمة\n  difference   Float @default(0) // عجز أو زيادة (+/-)\n\n  handedTo String  @default(\"المالك (Maestro)\") // تم تسليم الفلوس لمين\n  notes    String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 14. GENERAL TREASURY EXPENSES (مصروفات ونثريات الخزينة)\n// ----------------------------------------------------\nmodel TreasuryExpense {\n  id            String   @id @default(cuid())\n  branchId      String?\n  branch        Branch?  @relation(fields: [branchId], references: [id], onDelete: SetNull)\n  category      String // SUPPLIES, UTILITIES, RENT, REFRESHMENTS, MAINTENANCE, OTHER\n  amount        Float\n  paymentMethod String   @default(\"CASH\") // CASH, CARD, INSTAPAY, VODAFONE_CASH\n  description   String\n  recipientName String? // اسم المستلم / المورد\n  recordedBy    String   @default(\"الكاشير\")\n  date          DateTime @default(now())\n  createdAt     DateTime @default(now())\n}\n"
}

